mapper.select:
SELECT a.id, a.title, a.summary, a.cover, a.category_id, c.name AS category_name, a.author_id, u.nickname AS author_name, a.top, a.view_count, a.like_count, a.favorite_count, a.comment_count, a.publish_time FROM article a LEFT JOIN user u ON u.id = a.author_id LEFT JOIN category c ON c.id = a.category_id WHERE a.status = 1 AND a.category_id = #{q.categoryId}
AND (a.title LIKE CONCAT('%', #{q.keyword}, '%') OR a.summary LIKE CONCAT('%', #{q.keyword}, '%'))
ORDER BY a.top DESC,
a.view_count + a.like_count * 5 DESC a.publish_time DESC
LIMIT #{offset}, #{size}
